window.wp = window.wp || {};
window.WoowGalleryAdmin = window.WoowGalleryAdmin || {l10n: {}};
window.WoowGalleryAdmin.mixins = window.WoowGalleryAdmin.mixins || [];
window.WoowGalleryAdmin.Gallery = window.WoowGalleryAdmin.Gallery || {};
window.WoowGalleryAdmin.Skin = window.WoowGalleryAdmin.Skin || {};

window.WoowGalleryAdmin.Hook = {
  hooks: {},

  register: function(hookName, action, callback, context) {
    let names = hookName.split(' '), curName;
    for (let i = 0; i < names.length; i++) {
      curName = names[i];
      if (!this.exists(curName)) {
        this.hooks[curName] = {};
      }
      this.hooks[curName][action] = {callback: callback, context: context};
    }
  },

  call: function(hookName, args, context) {
    if ('undefined' !== typeof (this.hooks[hookName])) {
      for (let key in this.hooks[hookName]) {
        // skip loop if the property is from prototype
        if (!this.hooks[hookName].hasOwnProperty(key)) {
          continue;
        }

        let action = this.hooks[hookName][key];
        if (!context) {
          context = action.context;
        }
        if (false === action.callback.apply(context, args)) {
          break;
        }
      }
    }
  },

  exists: function(hookName) {
    return 'undefined' !== typeof (this.hooks[hookName]);
  },

  remove: function(hookName, action) {
    if (this.exists(hookName)) {
      delete this.hooks[hookName][action];
    }
  }
};


/**
 * Handles tabbed interfaces within WoowGallery:
 */

jQuery(function($) {

  // Define some general vars
  var woowgallery_tabs_nav = '.woowgallery-tabs-nav',     // Container of tab navigation items (typically an unordered list)
    woowgallery_tabs_hash = window.location.hash,
    woowgallery_tabs_current_tab = woowgallery_tabs_hash.replace('!', '').split('/')[0];

  // Update the form action to contain the selected tab as a hash in the URL
  // This means when the user saves their Gallery, they'll see the last selected tab 'open' on reload
  $(window).on('woowgallery_post_action', function() {
    var woowgallery_post_action = $('#post').attr('action');
    if (woowgallery_post_action) {
      // Remove any existing hash from the post action
      woowgallery_post_action = woowgallery_post_action.split('#')[0];

      // Append the selected tab as a hash to the post action
      $('#post').attr('action', woowgallery_post_action + window.location.hash);
    }
  });

  // Change tabs on click.
  // Tabs should be clickable elements, such as an anchor or label.
  $(woowgallery_tabs_nav).on('click', '.nav-tab, a', function(e) {

    // Prevent the default action
    e.preventDefault();

    // Get the clicked element and the nav tabs
    var woowgallery_tabs = $(this).closest(woowgallery_tabs_nav),
      woowgallery_tabs_section = $(woowgallery_tabs).data('container'),
      woowgallery_tab = ((typeof $(this).attr('href') !== 'undefined') ? $(this).attr('href') : $(this).data('tab'));

    // Don't do anything if we're clicking the already active tab.
    if ($(this).hasClass('woowgallery-active')) {
      return;
    }

    // Remove the active class from everything in this tab navigation and section
    $(woowgallery_tabs).find('.woowgallery-active').removeClass('woowgallery-active');
    $(woowgallery_tabs_section).find('div.woowgallery-active').removeClass('woowgallery-active');

    // Add the active class to the chosen tab and section
    $(this).addClass('woowgallery-active');
    $(woowgallery_tabs_section).find(woowgallery_tab).addClass('woowgallery-active');

    // Update the window URL to contain the selected tab as a hash in the URL.
    window.location.hash = woowgallery_tab.split('#').join('#!');
    // Update the form action to contain the selected tab as a hash in the URL
    $(window).trigger('woowgallery_post_action');

    // Code Editor refresh for misc tab.
    if (window.wgCodeEditor_custom_css && '#woowgallery-tab-misc' === woowgallery_tab) {
      window.wgCodeEditor_custom_css.codemirror.refresh();
    }
  });

  // If the URL contains a hash beginning with woowgallery-tab, mark that tab as open
  // and display that tab's panel.
  if (woowgallery_tabs_hash && woowgallery_tabs_hash.indexOf('woowgallery-tab-') >= 0) {
    // Find the tab panel that the tab corresponds to
    var woowgallery_tabs_section = $(woowgallery_tabs_current_tab).parent(),
      woowgallery_tab_nav = $(woowgallery_tabs_section).data('navigation');

    $(woowgallery_tab_nav).find('a[href="' + woowgallery_tabs_current_tab + '"]').trigger('click');

    // // Remove the active class from everything in this tab navigation and section
    // $(woowgallery_tab_nav).find('.woowgallery-active').removeClass('woowgallery-active');
    // $(woowgallery_tabs_section).find('div.woowgallery-active').removeClass('woowgallery-active');

    // // Add the active class to the chosen tab and section
    // $(woowgallery_tab_nav).find('a[href="' + woowgallery_tabs_current_tab + '"]').addClass('woowgallery-active');
    // $(woowgallery_tabs_current_tab).addClass('woowgallery-active');
    //
    // // Update the form action to contain the selected tab as a hash in the URL
    // $(window).trigger('woowgallery_post_action');
  }

});

/**
 * View gallery item
 */
(function($, _) {

  let woowgallery = window.WoowGalleryAdmin;

  woowgallery.mixins.push({
    data: function() {
      return {
        viewItem: false,
        viewItemCarousel: null
      };
    },
    computed: {
      viewItemIndex: function() {
        if (this.viewItem) {
          return _.findIndex(this.gallery_paged, {id: this.viewItem.id});
        }

        return -1;
      },
      // Edit next item.
      viewItemNext: function() {
        let index = this.viewItemIndex;
        if (index < 0 || (index + 1) >= this.gallery_paged.length) {
          return false;
        }

        return this.gallery_paged[index + 1];
      },

      // Edit previous item.
      viewItemPrev: function() {
        let index = this.viewItemIndex;
        if (index < 0 || (index - 1) < 0) {
          return false;
        }

        return this.gallery_paged[index - 1];
      }
    },
    watch: {
      viewItem: function(newEditItem, oldEditItem) {
        if (newEditItem) {
          if (!oldEditItem) {
            $('body').addClass('modal-open');
          }
          this.$nextTick(() => {
            this.viewItemCarouselInit();
          });
        }
        else {
          $('body').removeClass('modal-open');
          this.viewItemCarouselDestroy();
        }
      }
    },
    beforeDestroy() {
      this.$nextTick(() => {
        this.viewItemCarouselDestroy();
      });
    },
    methods: {
      // Trigger edit item modal window.
      viewItemSet: function(item, event) {
        if (!item || ['instagram'].indexOf(item.type) === false) {
          return false;
        }

        if (event) {
          event.preventDefault();
        }

        this.viewItem = _.find(this.gallery_paged, (media) => (media.id === item.id));
      },

      // Close edit item modal window.
      viewItemClose: function() {
        this.viewItem = false;
        this.viewItemCarouselDestroy();
      },

      viewItemCarouselInit: function() {
        this.viewItemCarouselDestroy();

        this.$nextTick(() => {
          const carousel = document.getElementById('carousel-' + this.viewItem.id);
          if (carousel) {
            var self = this;
            this.viewItemCarousel = new Swiper(carousel, {
              cssMode: true,
              navigation: {
                nextEl: '.swiper-button-next',
                prevEl: '.swiper-button-prev'
              },
              pagination: {
                el: '.swiper-pagination',
                clickable: true
              },
              on: {
                init: function() {
                  setTimeout(() => {
                    self.viewItemCarouselVideoPlayPause(this.activeIndex);
                  }, 0);
                },
                slideChange: function() {
                  self.viewItemCarouselVideoPlayPause(this.activeIndex);
                }
              }
            });
          }
        });
        this.$forceUpdate();
      },

      viewItemCarouselVideoPlayPause: function(activeIndex) {
        if (!this.viewItemCarousel) {
          return;
        }

        if (this.viewItemVideo) {
          this.viewItemVideo.pause();
        }
        this.viewItemVideo = null;
        let video = $('.swiper-slide', this.viewItemCarousel.$el).eq(activeIndex).find('video');
        if (video && video.length) {
          video[0].play();
          this.viewItemVideo = video[0];
        }
      },

      viewItemCarouselDestroy: function() {
        if (this.viewItemCarousel) {
          this.viewItemCarousel.destroy && this.viewItemCarousel.destroy();
          this.viewItemCarousel = null;
        }
      }
    }
  });

})(jQuery, _);

/**
 * Settings mixins
 */
(function($, _) {

  let woowgallery = window.WoowGalleryAdmin;

  woowgallery.mixins.push({
    methods: {
      setDefaults: function(obj, def_obj) {
        const setDefaults = (obj, def_obj) => {
          def_obj = def_obj || {};
          $.each(obj, function(key, val) {
            if (typeof val !== 'object') {
              return;
            }
            if (typeof val['default'] !== 'undefined') {
              def_obj[key] = val['default'];
            }
            else {
              setDefaults(val, def_obj);
            }
          });
          return def_obj;
        };

        return setDefaults(obj, def_obj);
      },

      // Get style classes of field
      getFieldRowClasses: function(field) {
        let baseClasses = {
          disabled: this.fieldDisabled(field),
          readonly: this.fieldReadonly(field),
          required: this.fieldRequired(field),
          'premium-field': this.fieldPremium(field)
        };

        if (_.isArray(field.styleClasses)) {
          _.each(field.styleClasses, (c) => {
            baseClasses[c] = true;
          });
        }
        else if (_.isString(field.styleClasses)) {
          baseClasses[field.styleClasses] = true;
        }

        baseClasses['field-' + field.tag] = true;

        return baseClasses;
      },

      // Get style classes of field
      getFieldRowStyles: function(field) {
        let styles = {};
        if (_.isObject(field.styles)) {
          styles = field.styles;
        }

        return styles;
      },

      // Should field type have a label?
      fieldTypeHasLabel: function(field) {
        let relevantType = field.type || field.tag;
        if (field.attr && field.attr.type) {
          relevantType = field.attr.type;
        }
        switch (relevantType) {
          case 'button':
          case 'submit':
          case 'reset':
            return false;
          default:
            return true;
        }
      },

      // Get disabled attr of field
      fieldDisabled: function(field) {
        if (!field.prop || !field.prop.disabled) {
          return false;
        }

        return field.prop.disabled;
      },

      // Get required prop of field
      fieldRequired: function(field) {
        if (!field.prop || !field.prop.required) {
          return false;
        }

        return field.prop.required;
      },

      // Get premium prop of field
      fieldPremium: function(field) {
        return !!field.premium;
      },

      // Get visible prop of field
      fieldVisible: function(field) {
        if (!field.visible) {
          return true;
        }

        let filter,
          visible;
        try {
          filter = compileExpression(field.visible);
          visible = filter(this.model);
        } catch (e) {
          visible = true;
        }

        return visible;
      },

      // Get readonly prop of field
      fieldReadonly: function(field) {
        if (!field.prop || !field.prop.readonly) {
          return false;
        }

        return field.prop.readonly;
      },

      // Get current hint.
      fieldHint: function(field) {
        return field.hint;
      },

      // Get type of field 'field-xxx'. It'll be the name of HTML element
      getFieldTagType: function(field) {
        return 'field-' + field.tag;
      }

    }
  });

})(jQuery, _);

/**
 * Vue Settings fields
 */

(function($) {

  let abstractField,
    components = {};

  abstractField = {
    props: [
      'skin',
      'schema',
      'id',
      'disabled',
      'options'
    ],
    data: function() {
      return {};
    },

    computed: {
      value: {
        get: function() {
          let val = null;
          if (!this.skin) {
            return;
          }
          if (typeof this.$root.model !== 'undefined' && this.id) {
            val = this.$root.model[this.id];
          }
          if (val === null) {
            val = this.schema.default;
          }
          return this.formatValueToField(val);
        },

        set: function(newValue) {
          if (!this.skin) {
            return;
          }
          newValue = this.formatValueToModel(newValue);
          if (this.id) {
            this.$root.model[this.id] = newValue;
            // this.$emit('model-updated', newValue, this.id);
          }
        }
      }
    },

    methods: {
      getFieldName: function() {
        let nameTemplate = this.options && this.options.fieldNameTemplate ? this.options.fieldNameTemplate : '{name}',
          name;
        if (this.schema.attr && this.schema.attr.name) {
          name = this.schema.attr.name;
        }
        name = name || this.schema.name || this.id;
        name = nameTemplate.replace('{name}', name);

        return name;
      },

      getFieldType: function(isInput) {
        let type;
        if (this.schema.attr && this.schema.attr.type) {
          type = this.schema.attr.type;
        }
        type = type || this.schema.type || 'text';

        if (isInput && 'color' === type) {
          return 'text';
        }
        return type;
      },

      getFieldID: function() {
        let prefix = this.options && this.options.fieldIdPrefix ? this.options.fieldIdPrefix : '',
          id;
        if (this.schema.attr && this.schema.attr.id) {
          id = this.schema.attr.id;
        }
        id = id || this.schema.id || this.id;

        return prefix + id;
      },

      getFieldClasses: function() {
        let classes = ['field-' + this.id];
        if (this.schema.attr && this.schema.attr.class) {
          if (_.isArray(this.schema.attr.class)) {
            _.union(classes, this.schema.attr.class);
          }
          else {
            classes.push(this.schema.attr.class);
          }
        }
        return classes;
      },

      getFieldAttributes: function() {
        let attrs = {},
          fieldType = this.getFieldType();
        if (fieldType && 'text' !== fieldType) {
          attrs['data-type'] = fieldType;
        }
        if (this.schema.attr) {
          attrs = $.extend(attrs, this.schema.attr);
        }
        if (this.schema.props) {
          let i = 0,
            length = this.schema.props.length,
            key;
          for (; i < length; i++) {
            key = this.schema.props[i];
            attrs[key] = true;
          }
        }
        return attrs;
      },

      formatValueToField: function(value) {
        return value;
      },

      formatValueToModel: function(value) {
        return value;
      }
    }
  };

  components['field-input'] = Vue.component('field-input',
    {
      mixins: [abstractField],
      template:
        `<div class="wrapper">
    <input class="form-control"
           :class="getFieldClasses()"
           :id="getFieldID()"
           :type="getFieldType(true)"
           :name="getFieldName()"
           v-model="value"
           v-bind="getFieldAttributes()"
    >
    <span class="helper" v-if="getFieldType() === 'color' || getFieldType() === 'range'">{{ value }}</span>
</div>`,
      data: function() {
        return {
          picker: null
        };
      },
      watch: {
        disabled: function(val) {
          if ('color' === this.getFieldType() && $.fn.spectrum) {
            if (val) {
              this.picker.spectrum('disable');
            }
            else {
              this.picker.spectrum('enable');
            }
          }
        }
      },
      mounted: function() {
        this.$nextTick(function() {
          if ('color' === this.getFieldType()) {
            if ($.fn.spectrum) {
              this.spectrumInit();
            }
            else {
              console.warn('Spectrum color library is missing.');
            }
          }
        });
      },
      updated: function() {
        this.$nextTick(function() {
          if ('color' === this.getFieldType() && $.fn.spectrum && this.picker) {
            this.picker.spectrum('set', this.value);
          }
        });
      },
      beforeDestroy: function() {
        if (this.picker) {
          this.picker.spectrum('destroy');
        }
      },
      methods: {
        spectrumInit: function() {
          let vm = this;
          if (this.picker) {
            this.picker.spectrum('destroy');
          }
          this.picker = $('input[data-type="color"]', this.$el).spectrum(
            _.defaults(
              this.schema.options || {},
              {
                color: this.value,
                showInput: true,
                showAlpha: true,
                disabled: this.disabled,
                allowEmpty: false,
                preferredFormat: 'rgb',
                change: function(color) {
                  vm.value = color ? color.toString() : null;
                }
              }
            )
          );
        },
        formatValueToModel: function(value) {
          if (value !== null) {
            let type = this.getFieldType();
            switch (type) {
              case 'number':
                return Number(value);
              case 'range':
                return Number(value);
            }
          }

          return value;
        }
      }
    });

  components['field-checkbox'] = Vue.component('field-checkbox',
    {
      mixins: [abstractField],
      template:
        `<div class="wrapper">
    <span class="wg-toggle" :class="{'is-checked': !!value}">
        <input type="hidden" :name="getFieldName()" value="0" />
        <input type="checkbox" :id="getFieldID()" :name="getFieldName()" :class="getFieldClasses()" v-bind="getFieldAttributes()" value="1" v-model="value" true-value="1" false-value="0">
        <span class="wg-toggle__track"></span>
        <span class="wg-toggle__thumb"></span>
    </span>
</div>`,
      methods: {
        formatValueToField: function(value) {
          return Number(value);
        },

        formatValueToModel: function(value) {
          if (value !== null) {
            return Number(value);
          }

          return value;
        }
      }
    });

  components['field-select'] = Vue.component('field-select',
    {
      mixins: [abstractField],
      template:
        `<div class="wrapper">
    <select class="form-control"
           v-model="value"
           :class="getFieldClasses()"
           :id="getFieldID()"
           :name="getFieldName()"
           v-bind="getFieldAttributes()"
    >
         <option v-for="item in items" :value="getItemValue(item)" :disabled="isItemDisabled(item)">{{ getItemName(item) }}</option>
    </select>
</div>`,
      data: function() {
        return {
          items: this.schema.options
        };
      },
      methods: {
        getItemValue: function(item) {
          if (_.isObject(item)) {
            if (typeof item['value'] !== 'undefined') {
              return item.value;
            }
            else {
              throw '`value` is not defined';
            }
          }
          else {
            return item;
          }
        },
        getItemName: function(item) {
          if (_.isObject(item)) {
            if (typeof item['name'] !== 'undefined') {
              return item.name;
            }
            else {
              throw '`name` is not defined';
            }
          }
          else {
            return item;
          }
        },
        isItemDisabled: function(item) {
          if (_.isObject(item)) {
            if (typeof item['premium'] !== 'undefined') {
              return item.premium && !config.premium;
            }
            else {
              return false;
            }
          }
          else {
            return false;
          }
        }
      }
    });

  window.WoowGalleryAdmin.vueFields = components;

})(jQuery);

/**
 * WoowGallery Lightbox Settings
 */

(function($) {
  let $lightbox_config = document.getElementById('woowgallery-lightbox-config');
  if (!$lightbox_config || !window.woowgallery_lightbox) {
    return;
  }

  let woowgallery = window.WoowGalleryAdmin;

  let config = new Vue({
    el: $lightbox_config,
    mixins: woowgallery.mixins,
    components: woowgallery.vueFields,
    data: {
      options: {
        fieldNameTemplate: '_woowgallery_lightbox[{name}]'
      },
      premium: false,
      lightbox: '',
      // lightbox settings
      model: {},
      // lightbox default settings
      defaults: {},
      // lightbox schema
      schema: {},
      activeTab: ''
    },
    computed: {
      isSettingsDefault: function() {
        let clean_model = _.pick(this.model, (val, key, obj) => {
          return this.defaults.hasOwnProperty(key);
        });

        return (JSON.stringify(clean_model) === JSON.stringify(this.defaults));
      },
      isSettingsChanged: function() {
        let model1 = JSON.stringify(this.model),
          model2 = JSON.stringify($.extend({}, this.defaults, window.woowgallery_lightbox[this.lightbox]['model']));
        return model1 !== model2;
      }
    },
    watch: {
      lightbox: function(lightbox) {
        if (!lightbox) {
          this.schema = {};
          this.activeTab = '';
          this.defaults = {};
          this.model = {};
          return;
        }
        this.schema = $.extend({}, window.woowgallery_lightbox[lightbox]['schema']);
        this.activeTab = _.keys(this.schema)[0];
        this.defaults = this.setDefaults(this.schema);
        this.model = $.extend({}, this.defaults, window.woowgallery_lightbox[lightbox]['model']);
      }
    },
    mounted: function() {
      // On init get gallery skin and set all the data
      this.premium = woowgallery.status && ('premium' === woowgallery.status || 'trial' === woowgallery.status);
      if (woowgallery.l10n.selected_lightbox || '' === woowgallery.l10n.selected_lightbox) {
        this.lightbox = woowgallery.l10n.selected_lightbox;
      }
      else {
        this.lightbox = woowgallery.l10n.default_lightbox;
      }
    },
    methods: {
      switchTab: function(tab_id) {
        this.activeTab = tab_id;
      },

      // reset settings changes
      resetLightboxSettingsChanges: function() {
        this.model = $.extend({}, this.defaults, window.woowgallery_lightbox[this.skin]['model']);
      },

      // reset skin settings to default
      resetLightboxSettings: function() {
        this.model = $.extend({}, this.defaults);
      }
    }
  });

  woowgallery.Lightbox = config;

})(jQuery);

